package com.eventpulse.service;
import com.eventpulse.model.Event;import java.time.*;import org.junit.jupiter.api.Test;import software.amazon.awssdk.services.scheduler.SchedulerClient;import software.amazon.awssdk.services.scheduler.model.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class EventScheduleServiceTest {Event event(String start){var e=new Event();e.setEventId("event-123");e.setStartDateTime(start);return e;}@Test void createsBothFutureReminderSchedules(){var client=mock(SchedulerClient.class);when(client.getSchedule(any(GetScheduleRequest.class))).thenThrow(ResourceNotFoundException.builder().message("missing").build());var service=new EventScheduleService(client,"group","arn:reminder","arn:role",Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));service.reschedule(event("2027-01-02T10:00:00Z"));verify(client,times(2)).createSchedule(any(CreateScheduleRequest.class));}
 @Test void roundsSubsecondReminderInstantsUpInsteadOfSchedulingEarly(){var client=mock(SchedulerClient.class);when(client.getSchedule(any(GetScheduleRequest.class))).thenThrow(ResourceNotFoundException.builder().message("missing").build());var service=new EventScheduleService(client,"group","arn:reminder","arn:role",Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));service.reschedule(event("2027-01-02T10:00:00.500000000Z"));var captor=org.mockito.ArgumentCaptor.forClass(CreateScheduleRequest.class);verify(client,times(2)).createSchedule(captor.capture());var expressions=captor.getAllValues().stream().map(CreateScheduleRequest::scheduleExpression).toList();org.junit.jupiter.api.Assertions.assertTrue(expressions.contains("at(2027-01-01T10:00:01)"));org.junit.jupiter.api.Assertions.assertTrue(expressions.contains("at(2027-01-02T09:00:01)"));}
 @Test void updatesExistingSchedulesIdempotently(){var client=mock(SchedulerClient.class);when(client.getSchedule(any(GetScheduleRequest.class))).thenReturn(GetScheduleResponse.builder().build());var service=new EventScheduleService(client,"group","arn:reminder","arn:role",Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));service.reschedule(event("2027-01-02T10:00:00Z"));verify(client,times(2)).updateSchedule(any(UpdateScheduleRequest.class));verify(client,never()).createSchedule(any(CreateScheduleRequest.class));}
 @Test void skipsReminderInstantsThatWouldBeInPast(){var client=mock(SchedulerClient.class);var service=new EventScheduleService(client,"group","arn:reminder","arn:role",Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));service.reschedule(event("2027-01-01T00:30:00Z"));verify(client,never()).createSchedule(any(CreateScheduleRequest.class));verify(client,times(2)).deleteSchedule(any(DeleteScheduleRequest.class));}
 @Test void cancellationDeletesBothStableNamesAndIgnoresMissingSchedules(){var client=mock(SchedulerClient.class);when(client.deleteSchedule(any(DeleteScheduleRequest.class))).thenThrow(ResourceNotFoundException.builder().message("missing").build());new EventScheduleService(client,"group","arn:reminder","arn:role").cancel("event-123");verify(client,times(2)).deleteSchedule(any(DeleteScheduleRequest.class));}}
